// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
var shipmentApi = app.MapGroup("api/shipments");

shipmentApi.MapGet("/", async (IShipmentService svc) =>
    Results.Ok(await svc.GetAllShipmentsAsync()))
    .RequireAuthorization();

shipmentApi.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
{
    var shipment = await svc.GetByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
}).RequireAuthorization();

shipmentApi.MapPut("/{id}/status", async (int id, UpdateShipmentStatusRequest request, IShipmentService svc) =>
{
    var shipment = await svc.UpdateStatusAsync(id, request.NewStatus);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

app.Run();

