                    <div class="row">
                        <div class="col-6">
                            <small class="text-muted">From</small>
                            <p class="mb-2">@trackedShipment.Origin</p>
                        </div>
                        <div class="col-6">
                            <small class="text-muted">To</small>
                            <p class="mb-2">@trackedShipment.Destination</p>
                        </div>
                    </div>
                    <div class="row">
                        <div class="col-6">
                            <small class="text-muted">Recipient</small>
                            <p class="mb-2">@trackedShipment.RecipientName</p>
                        </div>
                        <div class="col-6">
                            <small class="text-muted">Description</small>
                            <p class="mb-2">@trackedShipment.Description</p>
                        </div>
                    </div>
                    <hr />
                    <div class="row">
                        <div class="col-6">
                            <small class="text-muted">Estimated Delivery</small>
                            <p class="mb-0 fw-bold">
                                @(trackedShipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                            </p>
                        </div>
                        @if (trackedShipment.ActualDelivery.HasValue)
                        {
                            <div class="col-6">
                                <small class="text-muted">Delivered On</small>
                                <p class="mb-0 fw-bold text-success">
                                    @trackedShipment.ActualDelivery.Value.ToString("MMM dd, yyyy")
                                </p>
                            </div>
