@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingInput = string.Empty;
    private string? errorMessage;
    private ShipmentDto? trackedShipment;

    private async Task TrackShipment()
    {
        errorMessage = null;
        trackedShipment = null;

        if (string.IsNullOrWhiteSpace(trackingInput))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }

        trackedShipment = await ShipmentService.GetByTrackingNumberAsync(trackingInput.Trim());
        if (trackedShipment is null)
        {
            errorMessage = $"No shipment found for \"{trackingInput.Trim()}\".";
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }
}

