@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">📦 Shipment Tracker</h1>
    <p class="lead text-muted">Track your shipments in real time</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-8 col-lg-6">
        <div class="card shadow-sm">
            <div class="card-body p-4">
                <h5 class="card-title mb-3">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text"
                           class="form-control form-control-lg"
                           placeholder="Enter tracking number (e.g. TRK-2026-001)"
                           @bind="trackingInput"
                           @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary btn-lg" @onclick="TrackShipment">
                        Track
                    </button>
                </div>
                @if (!string.IsNullOrEmpty(errorMessage))
                {
                    <div class="alert alert-warning mt-3 mb-0">@errorMessage</div>
                }
            </div>
        </div>
    </div>
</div>

@if (trackedShipment is not null)
{
    <div class="row justify-content-center mt-4">
        <div class="col-md-8 col-lg-6">
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@trackedShipment.TrackingNumber</strong>
                    <span class="badge @trackedShipment.StatusBadgeClass">@trackedShipment.StatusDisplay</span>
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-6">
                            <small class="text-muted">From</small>
                            <p class="mb-2">@trackedShipment.Origin</p>
                        </div>
                        <div class="col-6">
                            <small class="text-muted">To</small>
                            <p class="mb-2">@trackedShipment.Destination</p>
                        </div>
                    </div>
                    <div class="row">
                        <div class="col-6">
                            <small class="text-muted">Recipient</small>
                            <p class="mb-2">@trackedShipment.RecipientName</p>
                        </div>
                        <div class="col-6">
                            <small class="text-muted">Description</small>
                            <p class="mb-2">@trackedShipment.Description</p>
                        </div>
                    </div>
                    <hr />
                    <div class="row">
                        <div class="col-6">
                            <small class="text-muted">Estimated Delivery</small>
                            <p class="mb-0 fw-bold">
                                @(trackedShipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                            </p>
                        </div>
                        @if (trackedShipment.ActualDelivery.HasValue)
                        {
                            <div class="col-6">
                                <small class="text-muted">Delivered On</small>
                                <p class="mb-0 fw-bold text-success">
                                    @trackedShipment.ActualDelivery.Value.ToString("MMM dd, yyyy")
                                </p>
                            </div>
                        }
                    </div>
                </div>
            </div>
        </div>
    </div>
}

<AuthorizeView>
    <Authorized>
        <div class="row justify-content-center mt-4">
            <div class="col-md-8 col-lg-6 text-center">
                <a href="dispatch" class="btn btn-outline-primary me-2">Dispatch Dashboard</a>
            </div>
        </div>
    </Authorized>
</AuthorizeView>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingInput = string.Empty;
    private string? errorMessage;
    private ShipmentDto? trackedShipment;

    private async Task TrackShipment()
    {
        errorMessage = null;
        trackedShipment = null;

        if (string.IsNullOrWhiteSpace(trackingInput))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }

        trackedShipment = await ShipmentService.GetByTrackingNumberAsync(trackingInput.Trim());
        if (trackedShipment is null)
        {
            errorMessage = $"No shipment found for \"{trackingInput.Trim()}\".";
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }
}

